class Solution {
public:
    vector<int> countVisitedNodes(vector<int>& edges) {
        int n = edges.size();
        vector<int> in_degree(n, 0);
        for (int v : edges) in_degree[v]++;
        vector<int> q;
        for (int i = 0; i < n; i++) if (in_degree[i] == 0) q.push_back(i);
        vector<int> topo;
        int head = 0;
        while (head < q.size()) {
            int u = q[head++];
            topo.push_back(u);
            int v = edges[u];
            if (--in_degree[v] == 0) q.push_back(v);
        }
        vector<int> ans(n, 0);
        for (int i = 0; i < n; i++) {
            if (in_degree[i] > 0 && ans[i] == 0) {
                vector<int> cycle;
                int curr = i;
                while (true) {
                    cycle.push_back(curr);
                    curr = edges[curr];
                    if (curr == i) break;
                }
                int sz = cycle.size();
                for (int node : cycle) ans[node] = sz;
            }
        }
        for (int i = (int)topo.size() - 1; i >= 0; i--) {
            int u = topo[i];
            ans[u] = ans[edges[u]] + 1;
        }
        return ans;
    }
};

class Solution {
    public int[] countVisitedNodes(List<Integer> edges) {
        int n = edges.size();
        int[] inDegree = new int[n];
        for (int v : edges) inDegree[v]++;
        Queue<Integer> q = new LinkedList<>();
        for (int i = 0; i < n; i++) if (inDegree[i] == 0) q.add(i);
        List<Integer> topo = new ArrayList<>();
        while (!q.isEmpty()) {
            int u = q.poll();
            topo.add(u);
            int v = edges.get(u);
            if (--inDegree[v] == 0) q.add(v);
        }
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            if (inDegree[i] > 0 && ans[i] == 0) {
                List<Integer> cycle = new ArrayList<>();
                int curr = i;
                while (true) {
                    cycle.add(curr);
                    curr = edges.get(curr);
                    if (curr == i) break;
                }
                int sz = cycle.size();
                for (int node : cycle) ans[node] = sz;
            }
        }
        for (int i = topo.size() - 1; i >= 0; i--) {
            int u = topo.get(i);
            ans[u] = ans[edges.get(u)] + 1;
        }
        return ans;
    }
}

